return ['project-id-version'=>'Google Authenticator 0.59','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/google-authenticator/','po-revision-date'=>'2026-11-26 14:12+0000','last-translator'=>'','language-team'=>'Swedish','language'=>'sv_SE','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','plural-forms'=>'nplurals=2; plural=n != 1;','x-domain'=>'google-authenticator','messages'=>[' Description that you\'ll see in the Google Authenticator app on your phone.'=>' Beskrivning som du kommer att se i Google Authenticator-appen på din mobil.',' Enabling an App password will decrease your overall login security.'=>' Att aktivera ett app-lösenord kommer att minska den övergripande inloggningssäkerheten.',' Password is not stored in cleartext, this is your only chance to see it.'=>' Lösenordet sparas inte i klartext, det här är din enda chans att se lösenordet.',' Relaxed mode allows for more time drifting on your phone clock (&#177;4 min).'=>' Tolerant läge tillåter större avvikelse i telefonens klocka (&#177;4 min).','<strong>ERROR</strong>: Google Authenticator was not turned on. Add the site to your authenticator app by scanning the QR code, then enter the code the app shows.'=>'<strong>FEL</strong>: Google Authenticator aktiverades inte. Lägg till webbplatsen i din autentiseringsapp genom att skanna QR-koden och skriv sedan in koden som appen visar.','<strong>ERROR</strong>: Please enter your Google Authenticator code.'=>'<strong>FEL</strong>: Ange din Google Authenticator-kod.','<strong>ERROR</strong>: The Google Authenticator code is missing.'=>'<strong>FEL</strong>: Google Authenticator-koden saknas.','<strong>ERROR</strong>: The Google Authenticator password is incorrect.'=>'<strong>FEL</strong>: Google Authenticator-lösenordet är felaktigt.','<strong>ERROR</strong>: The username, password or Google Authenticator code is incorrect, or the code has expired.'=>'<strong>FEL</strong>: Användarnamnet, lösenordet eller Google Authenticator-koden är felaktig, eller så har koden gått ut.','<strong>ERROR</strong>: Too many incorrect Google Authenticator codes. Please try again in %d minute.'=>'<strong>FEL</strong>: För många felaktiga Google Authenticator-koder. Försök igen om %d minut.' . "\0" . '<strong>FEL</strong>: För många felaktiga Google Authenticator-koder. Försök igen om %d minuter.','<strong>ERROR</strong>: Your new Google Authenticator secret was not saved. Scan the new QR code with your authenticator app, then enter the code the app shows.'=>'<strong>FEL</strong>: Din nya Google Authenticator-nyckel sparades inte. Skanna den nya QR-koden med din autentiseringsapp och skriv sedan in koden som appen visar.','Active'=>'Aktiv','After adding the site to your authenticator app, type the code it shows here.'=>'När du har lagt till webbplatsen i din autentiseringsapp skriver du in koden som visas här.','An account can also be added by typing in the secret. After you\'ve added your account to the App, please type the code you see on the screen into the Authenticator Code field and press the Verify Authenticator Code button.'=>'Ett konto kan också läggas till genom att skriva in nyckeln. När du har lagt till ditt konto i appen skriver du in koden som visas på skärmen i fältet ”Authenticator-kod” och klickar på knappen ”Verifiera Authenticator-kod”.','Android: Authy'=>'Android: Authy','Android: Google Authenticator'=>'Android: Google Authenticator','Android: Microsoft Authenticator'=>'Android: Microsoft Authenticator','Ask for authenticator code on secondary login screen'=>'Fråga efter engångskod på en särskild sida','Authenticator Code'=>'Authenticator-kod','Change network wide Google Authenticator settings'=>'Ändra nätverksövergripande inställningar för Google Authenticator','Congratulations, you have successfully enabled Google Authenticator for your account'=>'Grattis, du har aktiverat Google Authenticator för ditt konto','Create new password'=>'Skapa nytt lösenord','Create new secret'=>'Skapa ny nyckel','Description'=>'Beskrivning','Enable App password'=>'Aktivera app-lösenord','Google Authenticator'=>'Google Authenticator','Google Authenticator Settings'=>'Google Authenticator-inställningar','Google Authenticator code'=>'Google Authenticator-kod','Hide settings from user'=>'Dölj inställningar för användare','If the account setup was successful, you will be logged out, and will need to login again using your Username, Password and Authenticator code generated using the App on your mobile device.'=>'Om kontokonfigurationen lyckades kommer du att loggas ut och behöver logga in igen med ditt användarnamn, lösenord och engångskod genererad med appen på din mobila enhet.','If you don\'t have Google Authenticator enabled for your WordPress account, leave this field empty.'=>'Om du inte har aktiverat Google Authenticator för ditt WordPress-konto, lämna detta fält tomt.','If you haven\'t already done so, please install an authenticator app on your mobile device, for example:'=>'Om du inte redan har gjort det, installera en autentiseringsapp på din mobila enhet, till exempel:','Log In'=>'Logga in','Network Settings'=>'Nätverksinställningar','Network-wide settings in effect, only a super admin can modify them.'=>'Nätverksinställningar gäller, bara en superadmin kan ändra dem.','OTP code doesn\'t match supplied secret, please check you\'ve configured Authenticator correctly.'=>'Engångskoden matchar inte med nyckeln. Kontrollera så att du har satt upp Authenticator korrekt.','Only use network-wide settings, ignoring site settings.'=>'Använd enbart nätverksinställningar och ignorera webbplatsinställningar.','Please enter the Google Authenticator code using the app on your device.'=>'Ange Google Authenticator-koden med hjälp av appen på din enhet.','Relaxed mode'=>'Tolerant läge','Roles requiring Google Authenticator Enabled'=>'Roller som kräver att Google Authenticator är aktiverad','Scan this with the Google Authenticator app.'=>'Skanna detta med Google Authenticator-appen.','Secondary Login Screen'=>'Sekundär inloggningssida','Secret'=>'Nyckel','Show/Hide QR code'=>'Visa/dölj QR-kod','Sorry, this role is enabled at the network level and can only be disabled via the <a href="%s">network settings</a>'=>'Tyvärr, den här rollen är aktiverad på nätverksnivå och kan endast inaktiveras via <a href="%s">nätverksinställningarna</a>','Sorry, you can\'t disable checks for this role as it\'s enabled at the network level.'=>'Tyvärr kan du inte inaktivera kontroller för den här rollen eftersom den är aktiverad på nätverksnivå.','Successfully saved your settings for the network'=>'Dina inställningar för nätverket har sparats','Successfully saved your settings for the site'=>'Dina inställningar för webbplatsen har sparats','Super Admins'=>'Superadministratörer','The easiest way to enable your account is to add an account by scanning the QR code using the app.'=>'Det enklaste sättet att aktivera ditt konto är att lägga till ett konto genom att skanna QR-koden med appen.','Two Screen Signin'=>'Tvåsidsinloggning','Verify Authenticator Code'=>'Verifiera Authenticator-kod','iOS: Authy'=>'iOS: Authy','iOS: Google Authenticator'=>'iOS: Google Authenticator','iOS: Microsoft Authenticator'=>'iOS: Microsoft Authenticator']];
